(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.018+t*0.3)*12 + Math.cos(y*0.013-t*0.22)*8 + Math.sin((x+y)*0.008+t*0.15)*6;
  let wy = Math.cos(y*0.018-t*0.28)*12 + Math.sin(x*0.014+t*0.32)*8 + Math.cos((x-y)*0.009-t*0.18)*6;
  let sx = x+wx, sy = y+wy;
  wx = Math.sin(sx*0.025+t*0.4)*6 + Math.cos(sy*0.02-t*0.35)*4;
  wy = Math.cos(sy*0.022-t*0.38)*6 + Math.sin(sx*0.018+t*0.42)*4;
  sx += wx; sy += wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.15],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+4)*50, 0.11, 2.1, 1.05],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+1)*70, 0.085, 1.8, 0.88]
  ];
  let aS=0, iS=0, fS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    fS += Math.sin(d*f*1.3-t*sp*0.4+0.8)*w;
  }
  const n=8;
  const act=aS/n, inh=iS/n, feed=fS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.08-ang*2-t*2.0)*0.15;
  const voro = (() => {
    let md = 99;
    for (let i=0;i<5;i++) {
      const vx = 120+100*i+Math.sin(t*0.3+i*1.8)*40;
      const vy = 60+Math.cos(t*0.25+i*2.1)*30+Math.sin(i*0.7)*40;
      const d = Math.sqrt((sx-vx)**2+(sy-vy)**2);
      if(d<md) md=d;
    }
    return md;
  })();
  const cellWave = Math.sin(voro*0.15-t*1.5)*Math.exp(-voro*0.015);
  const rd1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + cellWave*0.4)*2.2);
  const rd2 = Math.tanh((feed*0.5 + rd1*1.2 - inh*0.4 + spiral*0.6)*1.8);
  const rd3 = Math.tanh((rd1*0.6 + rd2*0.8 + feed*0.3 - Math.abs(inh)*0.5)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.35-t*2.5)*0.1;
  const blend = rd3*0.55 + rd2*0.25 + cell*0.15 + micro*0.05;
  const v = blend*0.5+0.5;
  const pal = [
    [5,10,45],[10,40,80],[15,85,120],[20,140,135],[60,175,130],
    [180,200,80],[220,160,55],[210,100,65],[170,50,75],[90,20,60],[5,10,45]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const smooth = Math.smoothstep ? 0 : f*f*(3-2*f);
  const sf = f*f*(3-2*f);
  const lum = 0.75+Math.sin(rd3*Math.PI)*0.25;
  const edge = Math.abs(rd3)>0.65?1.2:Math.abs(rd3)>0.4?1.05:0.95;
  const glow = Math.max(0, 1-voro*0.02)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*20))|0,
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*40))|0,
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*60))|0
  ];
}
